#include<stdio.h>
int main(int argc, char *argv[])
{
    long long r1,r2,c1,c2,s1,s2;
    scanf("%lld%lld%lld%lld%lld%lld",&r1,&r2,&c1,&c2,&s1,&s2);
    long long a,b,c,d;
    if ((c1+s1-r2)%2 != 0 || (c2+s2-r2)%2 != 0) {
        printf("-1\n");
        return 0;
    }
    a=(c1+s1-r2)/2;
    b=(c2+s2-r2)/2;
    c=c1-a;
    d=s1-a;
    if (a<1 || a>9 || b<1 || b>9 || c<1 || c>9 || d<1 || d>9 ||
        a==b || a==c || a==d || b==c || b==d || c==d ||
        a+b!=r1 || c+d!=r2 || a+c!=c1 || b+d!=c2 || a+d!=s1 || b+c!=s2) {
        printf("-1\n");
    } else {
        printf("%lld %lld\n",a,b);
        printf("%lld %lld\n",c,d);
    }
    return 0;
}

